-- Free native integration of source contracts, research methods, journal and cached replay.
-- No external data service, new model, brokerage or financial policy is enabled.
begin;
create table if not exists paperlab.research_journal(seq bigint generated always as identity primary key,created_at timestamptz not null default now(),previous_hash text not null,entry_hash text not null unique,record jsonb not null check(octet_length(record::text)<=20000));
create or replace function paperlab.research_journal_append(p_record jsonb)returns void language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare h text;begin
 perform pg_advisory_xact_lock(hashtext('paperlab.free-research-journal'));select entry_hash into h from paperlab.research_journal order by seq desc limit 1;h:=coalesce(h,repeat('0',64));
 if exists(select 1 from paperlab.research_journal where record->>'event_key'=p_record->>'event_key')then return;end if;
 insert into paperlab.research_journal(previous_hash,entry_hash,record)values(h,encode(sha256(convert_to(h||E'\n'||p_record::text,'UTF8')),'hex'),p_record);
end$$;
revoke all on function paperlab.research_journal_append(jsonb)from public,anon,authenticated,service_role;
-- Import time is explicit; original pre-release timestamps are not rewritten.
do $$declare c record;begin for c in select id,symbol,cycle_key,forecast,frozen_at from paperlab.earnings_cycles where frozen_at is not null and forecast is not null order by frozen_at loop
 perform paperlab.research_journal_append(jsonb_build_object('event_key','legacy:'||c.id,'phase','legacy_forecast','symbol',c.symbol,'cycle',c.cycle_key,'original_recorded_at',c.frozen_at,'imported_at',now(),'forecast',c.forecast));
end loop;end$$;
create table if not exists paperlab.free_research_results(symbol text primary key,source_hash text not null,checked_at timestamptz not null default now(),record jsonb not null check(octet_length(record::text)<=20000));
create table if not exists paperlab.free_research_runtime(singleton boolean primary key default true check(singleton),enabled boolean not null default true,token uuid,lease_until timestamptz,payload jsonb,day date,used int not null default 0,last_attempt timestamptz,last_success timestamptz,status text not null default 'waiting');
insert into paperlab.free_research_runtime(singleton)values(true)on conflict do nothing;
do $$declare n text;begin foreach n in array array['research_journal','free_research_results','free_research_runtime']loop execute format('alter table paperlab.%I enable row level security',n);execute format('revoke all on paperlab.%I from public,anon,authenticated,service_role',n);end loop;end$$;
-- Canonicalize explicit short fiscal-year labels as well as full years.
create or replace function paperlab.quarter_fiscal_key(p text)returns text language sql immutable as $$select coalesce(substring(upper(p)from 'FISCAL(?: YEAR)?[ -]*(20[0-9]{2})'),substring(upper(p)from 'FY[ -]*(20[0-9]{2})'),substring(upper(p)from '20[0-9]{2}'),'20'||substring(upper(p)from 'FY[ -]*([0-9]{2})\M'))||'Q'||coalesce(substring(upper(p)from 'Q[ -]*([1-4])'),case when upper(p)~'FIRST[ -]+QUARTER'then'1'when upper(p)~'SECOND[ -]+QUARTER'then'2'when upper(p)~'THIRD[ -]+QUARTER'then'3'when upper(p)~'FOURTH[ -]+QUARTER'then'4'end)$$;
create or replace function public.paper_quarter_claim()returns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare model_ok boolean;r paperlab.quarter_runtime;j paperlab.quarter_jobs;b paperlab.deep_models;t uuid;p jsonb;charge bigint;m date:=date_trunc('month',now()at time zone'UTC')::date;d date:=(now()at time zone'America/Los_Angeles')::date;begin
 select *into r from paperlab.quarter_runtime where singleton for update;if not r.enabled or r.lease_until>now()then return null;end if;
 if not exists(select 1 from paperlab.gemini_runtime where free_tier_confirmed_at is not null)then return null;end if;
 update paperlab.quarter_jobs set status='retry',available_at=now()+interval'2 minutes'where id=r.job_id and status='leased';perform paperlab.quarter_plan();
 insert into paperlab.free_usage(month)values(m)on conflict do nothing;perform 1 from paperlab.free_usage where month=m for update;insert into paperlab.quarter_usage(month)values(m)on conflict do nothing;
 select *into b from paperlab.deep_models where model='gemini-3.5-flash-lite'for update;
 if b.day is distinct from d then b.used:=0;end if;if b.minute is distinct from date_trunc('minute',now())then b.minute_used:=0;b.minute_tokens:=0;end if;
 model_ok:=coalesce(b.used<b.daily_limit and b.minute_used<b.rpm and b.minute_tokens+100000<=b.tpm and coalesce(b.retry_after,'-infinity')<=now(),false);
 select *into j from paperlab.quarter_jobs where(model_ok or phase='actual')and status in('queued','retry','source_missing')and due_at<=now()and available_at<=now()and(phase<>'calendar'or((select calendar_reserved_bytes from paperlab.quarter_usage where month=m)+500000<=60000000 and(select estimated_worker_egress_bytes from paperlab.free_usage where month=m)+500000<paperlab.cached_research_limit()))and(phase not in('pre7','pre2')or(select release_at from paperlab.quarter_cycles where id=cycle_id)>now()+interval'24 hours')order by case phase when'pre7'then 0 when'pre2'then 1 when'actual'then 2 else 3 end,due_at limit 1 for update skip locked;
 if not found then update paperlab.quarter_runtime set status=case when not model_ok then'waiting_model_cooldown'else'waiting_work_quota_or_download_budget'end where singleton;return null;end if;
 p:=jsonb_build_object('cycle',(select to_jsonb(c)from paperlab.quarter_cycles c where id=j.cycle_id),'sources',(select coalesce(jsonb_agg(v),'[]')from(select jsonb_build_object('id',s.id,'url',s.url,'sha256',s.sha256,'known_at',s.known_at,'role',s.role,'kind',s.kind,'total_chars',length(s.body),'text',substring(s.body from 1 for case when j.phase='actual'then 40000 else 16000 end))v from paperlab.deep_documents s where s.symbol=j.symbol and s.active and s.body<>''and(j.phase<>'actual'or s.known_at>=(select release_at from paperlab.quarter_cycles where id=j.cycle_id))order by case when s.kind='earnings_release'then 0 when s.role='interim'then 1 else 2 end,s.known_at desc limit case when j.phase='actual'then 2 else 3 end)z),'reference_forecast',coalesce((select record from paperlab.quarter_forecasts where cycle_id=j.cycle_id),(select forecast from paperlab.earnings_cycles where id=(select legacy_id from paperlab.quarter_cycles where id=j.cycle_id))),'reporting_currency',(select record->'metrics'->'revenue'->>'currency'from paperlab.quarterly_expectations where symbol=j.symbol),'consensus',(select record from paperlab.analyst_consensus where symbol=j.symbol),'market_quote',(select jsonb_build_object('price',pf.state->'prices'->j.symbol,'time',pf.state->'last_observation'->j.symbol->>'time','scope','Indicatieve laatst opgeslagen koers, geen uitvoeringsprijs')from paperlab.portfolio pf limit 1),'company_report',(select report-'source_manifest'from paperlab.deep_companies where symbol=j.symbol),'previous_research',(select result->'assessment'from paperlab.quarter_jobs where cycle_id=j.cycle_id and phase in('pre7','pre2')and status='completed'order by completed_at desc limit 1),'previous_calendar',(select result->'assessment'from paperlab.quarter_jobs where symbol=j.symbol and phase='calendar'and status='completed'order by completed_at desc limit 1),'macro_context',paperlab.macro_context(),'limitations','Geen automatische aankoopgoedkeuring. Primaire bronnen, periodes en eenheden blijven vereist.');
 if j.phase<>'calendar'and jsonb_array_length(p->'sources')=0 then update paperlab.quarter_jobs set status='source_missing',available_at=now()+interval'6 hours',result='{"gaps":["Primaire brontekst ontbreekt"]}'where id=j.id;update paperlab.deep_companies set next_discovery=least(next_discovery,now())where symbol=j.symbol;update paperlab.quarter_runtime set status='waiting_primary_sources'where singleton;return null;end if;
 charge:=2*octet_length(p::text)+32000+case when j.phase='calendar'then 500000 else 0 end;
 if octet_length(p::text)>95000 then p:=p-'company_report';end if;
 if octet_length(p::text)>95000 then p:=jsonb_set(p,'{sources}',(select jsonb_agg(jsonb_set(value,'{text}',to_jsonb(left(value->>'text',8000))))from jsonb_array_elements(p->'sources')));end if;
 if octet_length(p::text)>95000 or pg_database_size(current_database())>paperlab.storage_limit('hard')or(select estimated_worker_egress_bytes+charge from paperlab.free_usage where month=m)>paperlab.cached_research_limit()then update paperlab.quarter_runtime set status='waiting_context_or_storage_or_traffic_budget'where singleton;return null;end if;
 t:=gen_random_uuid();update paperlab.quarter_runtime set token=t,lease_until=now()+interval'150 seconds',job_id=j.id,payload=p,last_attempt=now(),status='processing',reserved=model_ok,model_day=d,budget_month=m where singleton;
 update paperlab.quarter_jobs set status='leased',attempts=attempts+1 where id=j.id;
 if j.phase='calendar'then update paperlab.quarter_usage set calendar_reserved_bytes=calendar_reserved_bytes+500000 where month=m;end if;
 if model_ok then update paperlab.deep_models set day=d,used=b.used+1,minute=date_trunc('minute',now()),minute_used=b.minute_used+1,minute_tokens=b.minute_tokens+100000 where model=b.model;end if;
 update paperlab.free_usage set estimated_worker_egress_bytes=estimated_worker_egress_bytes+charge where month=m;
 return jsonb_build_object('token',t,'model_allowed',model_ok,'job',to_jsonb(j)||jsonb_build_object('calendar_cache',(select record from paperlab.quarter_calendar_cache where symbol=j.symbol),'calendar_url',(select calendar_url from paperlab.quarter_companies where symbol=j.symbol)),'input',p);
end$$;

do $$begin if to_regprocedure('public.paper_quarter_commit_workbench_base(uuid,jsonb)')is null then alter function public.paper_quarter_commit(uuid,jsonb)rename to paper_quarter_commit_workbench_base;end if;end$$;
-- Cached success is not evidence that provider capacity has recovered.
do $$declare s text;begin
 s:=pg_get_functiondef('public.paper_quarter_commit_workbench_base(uuid,jsonb)'::regprocedure);
 if position('if coalesce((p_result->>''attempted_calls'')::int,0)>0 then'in s)=0 then
 s:=replace(s,$old$update paperlab.deep_models set last_status='completed',provider_failures=0,retry_after=null where model='gemini-3.5-flash-lite';$old$,$new$if coalesce((p_result->>'attempted_calls')::int,0)>0 then update paperlab.deep_models set last_status='completed',provider_failures=0,retry_after=null where model='gemini-3.5-flash-lite';end if;$new$);execute s;
 end if;
end$$;
create or replace function public.paper_quarter_commit(p_token uuid,p_result jsonb)returns boolean language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare j paperlab.quarter_jobs;r paperlab.quarter_runtime;ok boolean;body jsonb;begin
 select *into r from paperlab.quarter_runtime where token=p_token and lease_until>now()for update;if not found then return false;end if;select *into j from paperlab.quarter_jobs where id=r.job_id;
 ok:=public.paper_quarter_commit_workbench_base(p_token,p_result);
 if ok and j.phase in('pre7','pre2','actual')and exists(select 1 from paperlab.quarter_jobs where id=j.id and status='completed')then
 body:=jsonb_build_object('event_key',j.id||':'||j.attempts,'protocol','free-research-workbench-v1','symbol',j.symbol,'cycle_id',j.cycle_id,'phase',j.phase,'recorded_at',now(),'source_ids',(select jsonb_agg(value->>'source_id')from jsonb_array_elements(coalesce(p_result->'evidence','[]'))),'method',coalesce(p_result->>'extraction_method','model_read'),'model',p_result->'model','summary',p_result->'summary','stance',p_result->'stance','direction',p_result->'direction','gaps',p_result->'gaps','forecast',jsonb_build_object('revenue_low',p_result->'revenue_low','revenue_base',p_result->'revenue_base','revenue_high',p_result->'revenue_high','eps_low',p_result->'eps_low','eps_base',p_result->'eps_base','eps_high',p_result->'eps_high','currency',p_result->'currency','eps_basis',p_result->'eps_basis'),'actual',case when j.phase='actual'then jsonb_build_object('revenue_value',p_result->'revenue_value','eps',p_result->'eps','period_end',p_result->'period_end','eps_basis',p_result->'eps_basis','currency',p_result->'currency')else null end,'trade_approval',false);
 perform paperlab.research_journal_append(body);
 end if;return ok;
end$$;
revoke all on function public.paper_quarter_commit_workbench_base(uuid,jsonb),public.paper_quarter_commit(uuid,jsonb),public.paper_quarter_claim()from public,anon,authenticated,service_role;
grant execute on function public.paper_quarter_commit(uuid,jsonb),public.paper_quarter_claim()to service_role;

create or replace function public.paper_free_research_claim()returns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare r paperlab.free_research_runtime;s paperlab.history_snapshots;p jsonb;m date:=date_trunc('month',now()at time zone'UTC')::date;d date:=(now()at time zone'UTC')::date;t uuid;begin
 select *into r from paperlab.free_research_runtime where singleton for update;if not r.enabled or r.lease_until>now()then return null;end if;
 if r.day is distinct from d then r.used:=0;end if;
 if r.used>=10 then update paperlab.free_research_runtime set status='waiting_daily_compute_budget'where singleton;return null;end if;
 insert into paperlab.free_usage(month)values(m)on conflict do nothing;perform 1 from paperlab.free_usage where month=m for update;
 if(select estimated_worker_egress_bytes+80000 from paperlab.free_usage where month=m)>paperlab.cached_research_limit()or pg_database_size(current_database())>paperlab.storage_limit('hard')then update paperlab.free_research_runtime set status='waiting_storage_or_transfer_budget'where singleton;return null;end if;
 select hs.*into s from paperlab.history_snapshots hs join paperlab.quarter_companies q on q.symbol=hs.symbol left join paperlab.free_research_results fr on fr.symbol=hs.symbol where hs.status='available'and jsonb_array_length(hs.data->'closes')>=100 and(fr.symbol is null or fr.source_hash is distinct from hs.hash or fr.record->>'protocol'is distinct from'cached-close-replay-v1')order by case when exists(select 1 from paperlab.quarter_cycles c where c.symbol=hs.symbol and c.release_at between now()-interval'14 days'and now()+interval'21 days')then 0 else 1 end,fr.checked_at nulls first,hs.symbol limit 1;
 if not found then update paperlab.free_research_runtime set status='cached_replays_up_to_date'where singleton;return null;end if;
 p:=jsonb_build_object('symbol',s.symbol,'source_hash',s.hash,'source_acquired_at',s.created_at,'currency',s.data->>'currency','actions',s.data->'actions','bars',(select jsonb_agg(v order by v->>'day')from(select jsonb_build_object('day',((to_timestamp((value#>>'{}')::double precision)at time zone coalesce(s.data->>'timezone','UTC'))::date)::text,'close',s.data->'closes'->(n::int-1))v from jsonb_array_elements(s.data->'timestamps')with ordinality a(value,n)order by n desc limit 180)z));
 if octet_length(p::text)>60000 then update paperlab.free_research_runtime set status='cached_context_too_large'where singleton;return null;end if;
 t:=gen_random_uuid();update paperlab.free_research_runtime set token=t,lease_until=now()+interval'90 seconds',payload=p,day=d,used=r.used+1,last_attempt=now(),status='processing'where singleton;
 update paperlab.free_usage set estimated_worker_egress_bytes=estimated_worker_egress_bytes+80000 where month=m;
 return jsonb_build_object('token',t,'input',p);
end$$;
create or replace function public.paper_free_research_commit(p_token uuid,p_result jsonb)returns boolean language plpgsql security definer set search_path=pg_catalog,pg_temp as $$declare r paperlab.free_research_runtime;begin
 select *into r from paperlab.free_research_runtime where token=p_token and lease_until>now()for update;if not found then return false;end if;
 if p_result->>'protocol'is distinct from'cached-close-replay-v1'or p_result->>'source_hash'is distinct from r.payload->>'source_hash'or p_result->>'symbol'is distinct from r.payload->>'symbol'or p_result->>'trade_approval'is distinct from'false'or p_result->>'paid_services'is distinct from'false'or p_result->>'profitability_proven'is distinct from'false'or p_result->>'retrospective'is distinct from'true'or coalesce(p_result->>'status','')not in('completed','insufficient_or_invalid_history','corporate_action_review')or octet_length(p_result::text)>20000 then raise exception'Bounded non-trading replay required';end if;
 insert into paperlab.free_research_results(symbol,source_hash,record)values(r.payload->>'symbol',r.payload->>'source_hash',p_result)on conflict(symbol)do update set source_hash=excluded.source_hash,record=excluded.record,checked_at=now();
 update paperlab.free_research_runtime set token=null,lease_until=null,payload=null,last_success=now(),status='processed'where singleton;return true;
end$$;
create or replace function public.paper_free_research_read(p_owner uuid,p_symbol text default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$begin
 if p_owner is distinct from(select owner_id from paperlab.settings where singleton)then raise exception'Owner required';end if;
 return jsonb_build_object('protocol','free-research-workbench-v1','runtime',(select to_jsonb(r)-'token'-'lease_until'-'payload'from paperlab.free_research_runtime r),'journal',jsonb_build_object('entries',(select count(*)from paperlab.research_journal),'chain_verified',not exists(select 1 from(select *,lag(entry_hash)over(order by seq)as prev from paperlab.research_journal)q where q.previous_hash<>coalesce(q.prev,repeat('0',64))or q.entry_hash<>encode(sha256(convert_to(q.previous_hash||E'\n'||q.record::text,'UTF8')),'hex')),'scope','Controle op wijzigingen binnen deze database; geen extern tijdstempel of bescherming tegen beheerderstoegang.'),'counts',(select jsonb_build_object('computed',count(*),'completed',count(*)filter(where record->>'status'='completed'),'needs_review',count(*)filter(where record->>'status'<>'completed'))from paperlab.free_research_results),'replays',(select coalesce(jsonb_agg(to_jsonb(f)),'[]')from(select *from paperlab.free_research_results where p_symbol is null or symbol=p_symbol order by checked_at desc,symbol limit case when p_symbol is null then 10 else 1 end)f),'paid_services',false,'trade_approval',false);
end$$;
do $$begin if to_regprocedure('public.paper_project_read_workbench_base(uuid,text)')is null then alter function public.paper_project_read(uuid,text)rename to paper_project_read_workbench_base;end if;end$$;
create or replace function public.paper_project_read(p_owner uuid,p_symbol text default null)returns jsonb language sql security definer set search_path=pg_catalog,pg_temp as $$select public.paper_project_read_workbench_base(p_owner,p_symbol)||jsonb_build_object('free_research',public.paper_free_research_read(p_owner,p_symbol))$$;
revoke all on function public.paper_free_research_claim(),public.paper_free_research_commit(uuid,jsonb),public.paper_free_research_read(uuid,text),public.paper_project_read_workbench_base(uuid,text),public.paper_project_read(uuid,text)from public,anon,authenticated,service_role;
grant execute on function public.paper_free_research_claim(),public.paper_free_research_commit(uuid,jsonb),public.paper_free_research_read(uuid,text),public.paper_project_read(uuid,text)to service_role;
do $$declare s text;begin if to_regprocedure('public.paper_project_backup_prepare()')is not null then s:=pg_get_functiondef('public.paper_project_backup_prepare()'::regprocedure);s:=replace(s,$old$'schema_version',44$old$,$new$'schema_version',45$new$);execute s;end if;end$$;
-- Retry the new cached parser on existing failed actuals; keep provider quotas/cooldowns intact.
update paperlab.quarter_jobs j set available_at=least(j.available_at,now())where j.phase='actual'and j.status in('retry','source_missing')and j.due_at<now()and exists(select 1 from paperlab.deep_documents d where d.symbol=j.symbol and d.active and d.kind='earnings_release'and d.body<>'');
commit;
